ALTER TABLE public.incidents ADD COLUMN assignee_staff text REFERENCES public.staff_members(id);
ALTER TABLE public.staff_messages ADD COLUMN task_id text REFERENCES public.tasks(id),ADD COLUMN attachment_path text;
CREATE TABLE public.visit_billing_terms(visit_id text PRIMARY KEY REFERENCES public.visits(id),base_amount numeric NOT NULL DEFAULT 120000 CHECK(base_amount>=0),extras numeric NOT NULL DEFAULT 0 CHECK(extras>=0),discount numeric NOT NULL DEFAULT 0 CHECK(discount>=0 AND discount<=base_amount+extras),reason text NOT NULL DEFAULT '',authorized_by uuid NOT NULL DEFAULT auth.uid(),authorized_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.visit_billing_terms TO authenticated;GRANT ALL ON public.visit_billing_terms TO service_role;ALTER TABLE public.visit_billing_terms ENABLE ROW LEVEL SECURITY;
CREATE POLICY "billing terms read" ON public.visit_billing_terms FOR SELECT TO authenticated USING(public.can_access_field_visit(visit_id));CREATE POLICY "billing terms authorize" ON public.visit_billing_terms FOR ALL TO authenticated USING(public.is_ops(auth.uid())) WITH CHECK(public.is_ops(auth.uid()));
CREATE FUNCTION public.guard_billing_terms() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM public.records r WHERE r.kind='cobro_campo' AND r.ref_id=NEW.visit_id AND r.status IN('informado','verificado')) THEN RAISE EXCEPTION 'No cambies tarifas después de informar un cobro';END IF;IF NEW.extras>0 AND btrim(NEW.reason)='' THEN RAISE EXCEPTION 'Explica los adicionales autorizados';END IF;NEW.authorized_by:=auth.uid();NEW.authorized_at:=now();RETURN NEW;END $$;
CREATE TRIGGER billing_terms_guard BEFORE INSERT OR UPDATE ON public.visit_billing_terms FOR EACH ROW EXECUTE FUNCTION public.guard_billing_terms();
CREATE TABLE public.field_files(path text PRIMARY KEY,user_id uuid NOT NULL DEFAULT auth.uid(),visit_id text REFERENCES public.visits(id),task_id text REFERENCES public.tasks(id),to_staff text REFERENCES public.staff_members(id),name text NOT NULL,mime text NOT NULL,size_bytes integer NOT NULL CHECK(size_bytes>0 AND size_bytes<=10485760),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,DELETE ON public.field_files TO authenticated;GRANT ALL ON public.field_files TO service_role;ALTER TABLE public.field_files ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.can_read_field_file(_path text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_staff(auth.uid()) AND EXISTS(SELECT 1 FROM public.field_files f WHERE f.path=_path AND (f.user_id=auth.uid() OR public.is_ops(auth.uid()) OR (f.visit_id IS NOT NULL AND public.can_access_field_visit(f.visit_id)) OR f.to_staff IN(SELECT public.my_staff_ids()) OR EXISTS(SELECT 1 FROM public.tasks t WHERE t.id=f.task_id AND t.staff_id IN(SELECT public.my_staff_ids())))) $$;
REVOKE ALL ON FUNCTION public.can_read_field_file(text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.can_read_field_file(text) TO authenticated;
CREATE POLICY "field files read" ON public.field_files FOR SELECT TO authenticated USING(public.can_read_field_file(path));
CREATE POLICY "field files upload metadata" ON public.field_files FOR INSERT TO authenticated WITH CHECK(public.is_staff(auth.uid()) AND user_id=auth.uid() AND path LIKE auth.uid()::text||'/%' AND (visit_id IS NULL OR public.can_access_field_visit(visit_id)) AND (task_id IS NULL OR EXISTS(SELECT 1 FROM public.tasks t WHERE t.id=task_id AND (public.is_ops(auth.uid()) OR t.staff_id IN(SELECT public.my_staff_ids())))));
CREATE POLICY "field files remove own" ON public.field_files FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE POLICY "field evidence upload" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='field-evidence' AND (storage.foldername(name))[1]=auth.uid()::text AND public.is_staff(auth.uid()));
CREATE POLICY "field evidence read" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='field-evidence' AND public.can_read_field_file(name));
CREATE POLICY "field evidence remove unlinked" ON storage.objects FOR DELETE TO authenticated USING(bucket_id='field-evidence' AND (storage.foldername(name))[1]=auth.uid()::text AND NOT EXISTS(SELECT 1 FROM public.staff_messages m WHERE m.attachment_path=name) AND NOT EXISTS(SELECT 1 FROM public.records r WHERE r.data->>'evidencePath'=name));
CREATE FUNCTION public.guard_field_file_delete() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM public.staff_messages m WHERE m.attachment_path=OLD.path) OR EXISTS(SELECT 1 FROM public.records r WHERE r.data->>'evidencePath'=OLD.path) THEN RAISE EXCEPTION 'El archivo ya forma parte de un registro';END IF;RETURN OLD;END $$;
CREATE TRIGGER field_file_delete_guard BEFORE DELETE ON public.field_files FOR EACH ROW EXECUTE FUNCTION public.guard_field_file_delete();
CREATE FUNCTION public.guard_field_message_context() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.visit_id IS NOT NULL AND NOT public.can_access_field_visit(NEW.visit_id) THEN RAISE EXCEPTION 'Sin acceso a esa visita';END IF;IF NEW.task_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.tasks t WHERE t.id=NEW.task_id AND (public.is_ops(auth.uid()) OR t.staff_id IN(SELECT public.my_staff_ids()))) THEN RAISE EXCEPTION 'Sin acceso a esa tarea';END IF;IF NEW.attachment_path IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.field_files f WHERE f.path=NEW.attachment_path AND f.user_id=auth.uid() AND f.visit_id IS NOT DISTINCT FROM NEW.visit_id AND f.task_id IS NOT DISTINCT FROM NEW.task_id AND f.to_staff IS NOT DISTINCT FROM NEW.to_staff) THEN RAISE EXCEPTION 'Adjunto no válido para este mensaje';END IF;RETURN NEW;END $$;
CREATE TRIGGER field_message_context_guard BEFORE INSERT ON public.staff_messages FOR EACH ROW EXECUTE FUNCTION public.guard_field_message_context();
CREATE FUNCTION public.guard_field_collection_contract() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE total numeric;reported numeric;BEGIN
 IF NEW.kind<>'cobro_campo' THEN RETURN NEW;END IF;
 IF TG_OP='INSERT' THEN
 IF NOT public.can_access_field_visit(NEW.ref_id) THEN RAISE EXCEPTION 'Sin acceso a esa visita';END IF;
 SELECT base_amount+extras-discount INTO total FROM public.visit_billing_terms WHERE visit_id=NEW.ref_id FOR UPDATE;IF total IS NULL THEN RAISE EXCEPTION 'Coordinación debe confirmar la tarifa';END IF;
 SELECT coalesce(sum((r.data->>'amount')::numeric),0) INTO reported FROM public.records r WHERE r.kind='cobro_campo' AND r.ref_id=NEW.ref_id AND r.status IN('informado','verificado');
 IF coalesce(NEW.data->>'amount','') !~ '^\d+(\.\d+)?$' THEN RAISE EXCEPTION 'Importe inválido';END IF;
 IF (NEW.data->>'amount')::numeric<=0 OR (NEW.data->>'amount')::numeric>total-reported THEN RAISE EXCEPTION 'El cobro supera el saldo autorizado';END IF;
 IF NEW.data->>'method' NOT IN('Efectivo','Transferencia / Nequi','Link de pago') THEN RAISE EXCEPTION 'Método de pago inválido';END IF;
 IF NEW.data->>'method'<>'Efectivo' AND coalesce(btrim(NEW.data->>'reference'),'')='' THEN RAISE EXCEPTION 'Incluye la referencia';END IF;
 IF NEW.data ? 'evidencePath' AND NOT EXISTS(SELECT 1 FROM public.field_files f WHERE f.path=NEW.data->>'evidencePath' AND f.user_id=auth.uid() AND f.visit_id=NEW.ref_id) THEN RAISE EXCEPTION 'Comprobante no autorizado';END IF;
 END IF;RETURN NEW;END $$;
CREATE TRIGGER field_collection_contract_guard BEFORE INSERT OR UPDATE ON public.records FOR EACH ROW EXECUTE FUNCTION public.guard_field_collection_contract();
CREATE FUNCTION public.field_billing_balance(_visit text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE total numeric;paid numeric;reported numeric;BEGIN IF NOT public.can_access_field_visit(_visit) THEN RAISE EXCEPTION 'Sin acceso';END IF;SELECT base_amount+extras-discount INTO total FROM public.visit_billing_terms WHERE visit_id=_visit;SELECT coalesce(sum((data->>'amount')::numeric) FILTER(WHERE status='verificado'),0),coalesce(sum((data->>'amount')::numeric) FILTER(WHERE status='informado'),0) INTO paid,reported FROM public.records WHERE kind='cobro_campo' AND ref_id=_visit;RETURN jsonb_build_object('authorized',total,'verified',paid,'reported',reported,'balance',greatest(0,total-paid),'availableToReport',greatest(0,total-paid-reported));END $$;
REVOKE ALL ON FUNCTION public.field_billing_balance(text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.field_billing_balance(text) TO authenticated;
CREATE FUNCTION public.guard_handover_items() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE item jsonb;src text;dst text;BEGIN IF NEW.kind<>'handover' OR TG_OP<>'INSERT' THEN RETURN NEW;END IF;src:=NEW.data->>'from';dst:=NEW.data->>'to';FOR item IN SELECT * FROM jsonb_array_elements(NEW.data->'items') LOOP
 IF NOT(EXISTS(SELECT 1 FROM public.tasks t WHERE t.id=item->>'id' AND t.staff_id=src AND NOT t.done AND coalesce(t.stage,'assigned')<>'cancelled') OR EXISTS(SELECT 1 FROM public.visit_participants p WHERE p.visit_id=item->>'id' AND p.staff_id=src AND p.active AND p.support_state<>'COMPLETED' AND EXISTS(SELECT 1 FROM public.staff_members m WHERE m.id=dst AND m.role='Auxiliar')) OR EXISTS(SELECT 1 FROM public.incidents i WHERE i.id=item->>'id' AND i.status<>'cerrada' AND (i.assignee_staff=src OR i.owner=(SELECT name FROM public.staff_members WHERE id=src)))) THEN RAISE EXCEPTION 'El pendiente no te pertenece o ya está resuelto; las visitas clínicas las reasigna Coordinación';END IF;
 END LOOP;RETURN NEW;END $$;
CREATE TRIGGER handover_items_guard BEFORE INSERT ON public.records FOR EACH ROW EXECUTE FUNCTION public.guard_handover_items();
CREATE FUNCTION public.guard_task_handover() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND NEW.staff_id IS DISTINCT FROM OLD.staff_id AND EXISTS(SELECT 1 FROM public.records r WHERE r.kind='handover' AND r.status='ACEPTADO' AND r.data->>'from'=OLD.staff_id AND r.data->>'to'=NEW.staff_id AND r.data->'items' @> jsonb_build_array(jsonb_build_object('id',OLD.id))) AND NEW.staff_id IN(SELECT public.my_staff_ids()) THEN NEW.stage:=coalesce(OLD.stage,'assigned');NEW.done:=OLD.done;NEW.version:=OLD.version+1;NEW.history:=OLD.history||jsonb_build_array(jsonb_build_object('transferFrom',OLD.staff_id,'transferTo',NEW.staff_id,'actor',auth.uid(),'at',now()));END IF;RETURN NEW;END $$;
CREATE TRIGGER aaa_task_handover BEFORE UPDATE ON public.tasks FOR EACH ROW EXECUTE FUNCTION public.guard_task_handover();
CREATE OR REPLACE FUNCTION public.guard_advanced_task() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE prev text;nxt text;transfer boolean;BEGIN
 IF TG_OP='INSERT' THEN IF auth.uid() IS NOT NULL AND NOT public.is_ops(auth.uid()) THEN RAISE EXCEPTION 'Solo Coordinación asigna tareas';END IF;NEW.stage:=CASE WHEN NEW.done THEN 'completed' ELSE 'assigned' END;NEW.version:=1;NEW.history:=jsonb_build_array(jsonb_build_object('state',NEW.stage,'actor',auth.uid(),'at',now()));RETURN NEW;END IF;
 prev:=coalesce(OLD.stage,CASE WHEN OLD.done THEN 'completed' ELSE 'assigned' END);IF prev IN('completed','cancelled') THEN RAISE EXCEPTION 'Una tarea resuelta no se modifica';END IF;
 transfer:=NEW.staff_id IS DISTINCT FROM OLD.staff_id AND NEW.staff_id IN(SELECT public.my_staff_ids()) AND EXISTS(SELECT 1 FROM public.records r WHERE r.kind='handover' AND r.status='ACEPTADO' AND r.data->>'from'=OLD.staff_id AND r.data->>'to'=NEW.staff_id AND r.data->'items' @> jsonb_build_array(jsonb_build_object('id',OLD.id)));
 IF transfer THEN RETURN NEW;END IF;
 IF NOT public.is_ops(auth.uid()) AND (NEW.staff_id IS DISTINCT FROM OLD.staff_id OR NEW.title<>OLD.title OR NEW.visit_id IS DISTINCT FROM OLD.visit_id OR NEW.due_at IS DISTINCT FROM OLD.due_at OR NEW.critical<>OLD.critical) THEN RAISE EXCEPTION 'Solo Coordinación cambia la asignación';END IF;
 nxt:=coalesce(NEW.stage,CASE WHEN NEW.done THEN 'completed' ELSE 'assigned' END);IF NEW.done<>OLD.done AND nxt=prev THEN nxt:=CASE WHEN NEW.done THEN 'completed' ELSE 'assigned' END;END IF;
 IF nxt<>prev THEN IF NEW.version<>OLD.version+1 THEN RAISE EXCEPTION 'La tarea cambió; recarga';END IF;IF NOT((prev='assigned' AND nxt='accepted') OR(prev='accepted' AND nxt IN('in_progress','blocked')) OR(prev='in_progress' AND nxt IN('completed','blocked')) OR(prev='blocked' AND nxt='in_progress') OR(nxt='cancelled' AND public.is_ops(auth.uid()))) THEN RAISE EXCEPTION 'Paso no permitido';END IF;IF nxt IN('blocked','cancelled') AND btrim(NEW.reason)='' THEN RAISE EXCEPTION 'Indica el motivo';END IF;NEW.history:=OLD.history||jsonb_build_array(jsonb_build_object('from',prev,'state',nxt,'reason',NEW.reason,'actor',auth.uid(),'at',now()));ELSE NEW.history:=OLD.history;NEW.version:=OLD.version;END IF;NEW.stage:=nxt;NEW.done:=nxt='completed';RETURN NEW;END $$;
CREATE FUNCTION public.apply_field_handover() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE item jsonb;src text;dst text;p public.visit_participants%ROWTYPE;BEGIN IF NEW.kind<>'handover' OR NEW.status<>'ACEPTADO' OR OLD.status<>'PENDIENTE_ACEPTACION' THEN RETURN NEW;END IF;src:=NEW.data->>'from';dst:=NEW.data->>'to';FOR item IN SELECT * FROM jsonb_array_elements(NEW.data->'items') LOOP
 IF EXISTS(SELECT 1 FROM public.tasks t WHERE t.id=item->>'id' AND t.staff_id=src AND NOT t.done AND coalesce(t.stage,'assigned')<>'cancelled') THEN UPDATE public.tasks SET staff_id=dst WHERE id=item->>'id' AND staff_id=src;
 ELSIF EXISTS(SELECT 1 FROM public.visit_participants vp WHERE vp.visit_id=item->>'id' AND vp.staff_id=src AND vp.active AND vp.support_state<>'COMPLETED') THEN
 SELECT * INTO p FROM public.visit_participants WHERE visit_id=item->>'id' AND staff_id=src FOR UPDATE;
 UPDATE public.visit_participants SET active=false WHERE id=p.id;
 INSERT INTO public.visit_participants(visit_id,staff_id) VALUES(p.visit_id,dst);
 ELSIF EXISTS(SELECT 1 FROM public.incidents i WHERE i.id=item->>'id' AND i.status<>'cerrada' AND (i.assignee_staff=src OR i.owner=(SELECT name FROM public.staff_members WHERE id=src))) THEN UPDATE public.incidents SET assignee_staff=dst,owner=(SELECT name FROM public.staff_members WHERE id=dst) WHERE id=item->>'id';
 ELSE RAISE EXCEPTION 'Un pendiente cambió antes de aceptar; solicita otra entrega';END IF;END LOOP;RETURN NEW;END $$;
CREATE TRIGGER field_handover_apply AFTER UPDATE ON public.records FOR EACH ROW EXECUTE FUNCTION public.apply_field_handover();
CREATE OR REPLACE FUNCTION public.guard_support_participant() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE nxt text;handoff boolean;BEGIN
 handoff:=EXISTS(SELECT 1 FROM public.records r WHERE r.kind='handover' AND r.status='ACEPTADO' AND r.data->'items' @> jsonb_build_array(jsonb_build_object('id',NEW.visit_id)) AND r.data->>'to' IN(SELECT public.my_staff_ids()) AND ((TG_OP='INSERT' AND r.data->>'to'=NEW.staff_id) OR(TG_OP='UPDATE' AND r.data->>'from'=NEW.staff_id AND NOT NEW.active)));
 IF TG_OP='INSERT' THEN IF NOT public.is_ops(auth.uid()) AND auth.uid() IS NOT NULL AND NOT handoff THEN RAISE EXCEPTION 'Solo Coordinación asigna auxiliares';END IF;IF NOT EXISTS(SELECT 1 FROM public.staff_members m WHERE m.id=NEW.staff_id AND m.role='Auxiliar') THEN RAISE EXCEPTION 'Elige un auxiliar';END IF;IF EXISTS(SELECT 1 FROM public.visits v WHERE v.id=NEW.visit_id AND v.status IN('finalizada','cancelada')) THEN RAISE EXCEPTION 'Visita resuelta';END IF;NEW.support_state:='ASSIGNED';NEW.version:=1;NEW.history:=jsonb_build_array(jsonb_build_object('state','ASSIGNED','actor',auth.uid(),'at',now()));RETURN NEW;END IF;
 IF NEW.visit_id<>OLD.visit_id OR NEW.staff_id<>OLD.staff_id OR NEW.created_by IS DISTINCT FROM OLD.created_by THEN RAISE EXCEPTION 'Identidad inmutable';END IF;
 IF NOT OLD.active OR OLD.support_state='COMPLETED' THEN RAISE EXCEPTION 'Apoyo ya resuelto';END IF;
 IF NEW.active<>OLD.active AND NOT public.is_ops(auth.uid()) AND NOT handoff THEN RAISE EXCEPTION 'Solo Coordinación cambia la asignación';END IF;
 IF handoff AND NEW.active<>OLD.active THEN NEW.history:=OLD.history||jsonb_build_array(jsonb_build_object('transfer','accepted','actor',auth.uid(),'at',now()));RETURN NEW;END IF;
 IF NEW.support_state<>OLD.support_state THEN IF NEW.staff_id NOT IN(SELECT public.my_staff_ids()) THEN RAISE EXCEPTION 'Cada auxiliar registra su apoyo';END IF;nxt:=CASE OLD.support_state WHEN 'ASSIGNED' THEN 'PREPARING' WHEN 'PREPARING' THEN 'READY' WHEN 'READY' THEN 'EN_ROUTE' WHEN 'EN_ROUTE' THEN 'ARRIVED' WHEN 'ARRIVED' THEN 'COMPLETED' END;IF NEW.support_state IS DISTINCT FROM nxt OR NEW.version<>OLD.version+1 THEN RAISE EXCEPTION 'Paso o versión inválidos';END IF;IF NEW.support_state='READY' AND NOT(coalesce((SELECT prep FROM public.visits WHERE id=NEW.visit_id),'{}') <@ NEW.prep_checked) THEN RAISE EXCEPTION 'Completa la preparación';END IF;NEW.history:=OLD.history||jsonb_build_array(jsonb_build_object('state',NEW.support_state,'actor',auth.uid(),'at',now()));ELSE IF NEW.version<>OLD.version THEN RAISE EXCEPTION 'La participación cambió';END IF;IF NEW.prep_checked IS DISTINCT FROM OLD.prep_checked AND (NEW.staff_id NOT IN(SELECT public.my_staff_ids()) OR OLD.support_state NOT IN('ASSIGNED','PREPARING')) THEN RAISE EXCEPTION 'No puedes cambiar la preparación';END IF;NEW.history:=OLD.history;END IF;RETURN NEW;END $$;
REVOKE ALL ON FUNCTION public.guard_billing_terms(),public.guard_field_file_delete(),public.guard_field_message_context(),public.guard_field_collection_contract(),public.guard_handover_items(),public.guard_task_handover(),public.apply_field_handover() FROM PUBLIC,anon;